const norm=s=>String(s==null?'':s).trim();
const vr=(input.ranges||[]).map(v=>v.valueRange||v).find(v=>String(v.range||'').includes('הקדמה מיידית'))||{};
const log=vr.values||[]; const id=norm(input.id);
// RULE (15/11/2026, כפילויות): אם אין מספר לקוח בלוג (עמודה E) - לוקחים אותו מדוח המכר לפי הטלפון (9 ספרות אחרונות) מקריאת הדוח במודול 90 (אם נכשלה - כמו קודם), לשונית החודש הנוכחי קודם; עדיפות לשורה עם אותו שם; אם יש כמה מספרים שונים בלי התאמת שם - לא מנחשים. Do not remove.
const cnFromReport=(ph,nmv)=>{const l9=s=>{const d=String(s==null?'':s).replace(/\D/g,'');return d.length>=9?d.slice(-9):'';};const nn=s=>String(s==null?'':s).replace(/[\s\u200e\u200f]+/g,' ').trim();const p=l9(ph);if(!p)return '';const c=[];for(const v of (Array.isArray(input.rep_ranges)?input.rep_ranges:[])){const x=(v&&v.valueRange)||v||{};const rg=String(x.range||'');if(rg.includes('הקדמה מיידית')||rg.includes('יעדים'))continue;for(const r of (x.values||[]).slice(1)){const g=String((r||[])[6]==null?'':r[6]).replace(/\D/g,'');if(g&&l9(r[3])===p)c.push({g,n:nn(r[2])});}}const byN=c.filter(x=>x.n&&x.n===nn(nmv));if(byN.length)return byN[0].g;return c.length&&c.every(x=>x.g===c[0].g)?c[0].g:'';};
for(let i=log.length-1;i>=1;i--){ if(id&&norm(log[i][10])===id) return {found:true,cn:norm(log[i][4]).replace(/\D/g,'')||cnFromReport(log[i][3],log[i][2])}; }
return {found:false,cn:''};

// RULE (Steve 12/11/2026): customer's answer to the advance time-window question (after "כן" on the immediate advance offer for tomorrow / Sunday).
// Only numbers 1-5 (one or more) -> email request to the company (same mailbox/format as the rep bot) + rep update. Anything else (exact hour, free text), offer "היום", too late, Fri/Sat, after 19:00, open/approved request -> to the selling rep. Do not remove.
const BIDI=new RegExp('[\\s'+String.fromCharCode(8206,8207)+']+','g'); const norm=s=>String(s==null?'':s).replace(BIDI,' ').trim();
const vrs=input.ranges||[];
const rangeOf=vr=>String((vr.valueRange||vr||{}).range||'');
const valsOf=vr=>((vr.valueRange||vr||{}).values)||[];
const log=valsOf(vrs.find(v=>rangeOf(v).includes('הקדמה מיידית'))||{});
const targets=valsOf(vrs.find(v=>rangeOf(v).includes('יעדים'))||{}).filter(r=>r&&norm(r[0]));
const id=norm(input.id); const reply=norm(input.reply);
const HM=['ינואר','פברואר','מרץ','אפריל','מאי','יוני','יולי','אוגוסט','ספטמבר','אוקטובר','נובמבר','דצמבר'];
const DAYS=['ראשון','שני','שלישי','רביעי','חמישי','שישי','שבת'];
const SL={1:8,2:10,3:12,4:14,5:16};
const nowIL=input.now?new Date(input.now):new Date(new Date().toLocaleString('en-US',{timeZone:'Asia/Jerusalem'}));
const today=new Date(nowIL.getFullYear(),nowIL.getMonth(),nowIL.getDate());
const dow=nowIL.getDay(), mins=nowIL.getHours()*60+nowIL.getMinutes();
const stamp=nowIL.getDate()+'/'+(nowIL.getMonth()+1)+' '+String(nowIL.getHours()).padStart(2,'0')+':'+String(nowIL.getMinutes()).padStart(2,'0');
// RULE (15/11/2026, כפילויות): אם אין מספר לקוח בלוג (עמודה E) - לוקחים אותו מדוח המכר לפי הטלפון (9 ספרות אחרונות) מקריאת הדוח במודול 90 (אם נכשלה - כמו קודם), לשונית החודש הנוכחי קודם; עדיפות לשורה עם אותו שם; אם יש כמה מספרים שונים בלי התאמת שם - לא מנחשים. Do not remove.
const cnFromReport=(ph,nmv)=>{const l9=s=>{const d=String(s==null?'':s).replace(/\D/g,'');return d.length>=9?d.slice(-9):'';};const nn=s=>String(s==null?'':s).replace(/[\s\u200e\u200f]+/g,' ').trim();const p=l9(ph);if(!p)return '';const c=[];for(const v of (Array.isArray(input.rep_ranges)?input.rep_ranges:[])){const x=(v&&v.valueRange)||v||{};const rg=String(x.range||'');if(rg.includes('הקדמה מיידית')||rg.includes('יעדים'))continue;for(const r of (x.values||[]).slice(1)){const g=String((r||[])[6]==null?'':r[6]).replace(/\D/g,'');if(g&&l9(r[3])===p)c.push({g,n:nn(r[2])});}}const byN=c.filter(x=>x.n&&x.n===nn(nmv));if(byN.length)return byN[0].g;return c.length&&c.every(x=>x.g===c[0].g)?c[0].g:'';};
let row=-1; for(let i=log.length-1;i>=1;i--){ if(norm(log[i][10])===id){row=i;break;} }
if(row<0||!id) return {found:false,mode:'none'};
const r=log[row];
const name=norm(r[2]), phone=norm(r[3]), cn=norm(r[4]).replace(/\D/g,'')||cnFromReport(r[3],r[2]), rep=norm(r[5]), offer=norm(r[8]), tab=norm(r[9]);
const toIntl=p=>{let d=String(p||'').replace(/\D/g,''); if(d.startsWith('972')) return d; if(d.startsWith('0')) d=d.slice(1); return d?'972'+d:'';};
let m=targets.filter(x=>norm(x[0])===rep); if(!m.length&&rep){const f=rep.split(' ')[0]; m=targets.filter(x=>{const a=norm(x[0]); return a===f||a.split(' ')[0]===f;});}
const repPh=m.length?toIntl(m[0][1]):''; const first=m.length?norm(m[0][0]).split(' ')[0]:rep.split(' ')[0];
// sent date (col A d/m/yyyy)
const sm=norm(r[0]).match(/(\d{1,2})\/(\d{1,2})\/(\d{4})/);
const sent=sm?new Date(+sm[3],+sm[2]-1,+sm[1]):today;
let target=null;
if(/ראשון/.test(offer)){ target=new Date(sent); do{target.setDate(target.getDate()+1);}while(target.getDay()!==0); }
else if(/מחר/.test(offer)){ target=new Date(sent); target.setDate(target.getDate()+1); while(target.getDay()===5||target.getDay()===6) target.setDate(target.getDate()+1); }
// parse: only digits 1-5 with separators
// RULE (18/11/2026): "או" is a separator too ("4 או 5"), and punctuation around the answer ("4 או 5.") is ignored. Do not remove.
const clean=reply.replace(/[⃣️]/g,' ').replace(/\s+/g,' ').trim().replace(/^[\s.,!?;:]+|[\s.,!?;:]+$/g,'');
const onlyNums=/^[1-5](?:(?:[\s,.\/+&-]|או|ו)+[1-5])*$/.test(clean);
const picks=onlyNums?[...new Set((clean.match(/[1-5]/g)||[]).map(Number))].sort((a,b)=>a-b):[];
let reason='';
if(!/ראשון|מחר/.test(offer)) reason='ההצעה ללקוח הייתה להיום - הקדמה להיום עוברת דרך משווקים יס';
else if(!picks.length) reason='הלקוח לא ענה במספרים מהרשימה';
else if(!cn) reason='אין ללקוח מספר לקוח בדוח המכר';
else if(!target||target.getTime()<=today.getTime()) reason='הלקוח ענה מאוחר מדי - היום המבוקש כבר הגיע';
else if(dow>4||mins>=19*60||mins<8*60) reason='הלקוח ענה מחוץ לשעות (אחרי 19:00 / סוף שבוע) - אי אפשר לשלוח לחברה בזמן';
const st=norm(input.ds_status), sday=norm(input.ds_send_day), stoday=+input.ds_sends_today||0;
const iso=d=>d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0')+'-'+String(d.getDate()).padStart(2,'0');
const todayIso=iso(today);
if(!reason&&st){
  if(st==='אושר') reason='כבר אושרה הקדמה ללקוח הזה בעבר';
  else if(st==='ממתין') reason='כבר יש בקשת הקדמה פתוחה על הלקוח הזה';
  else if(sday===todayIso&&stoday>=2) reason='כבר נשלחו היום 2 בקשות הקדמה על הלקוח הזה';
}
const fullDate=target?'יום '+DAYS[target.getDay()]+' '+target.getDate()+' '+HM[target.getMonth()]+' '+target.getFullYear():'';
const shortDate=target?target.getDate()+'/'+(target.getMonth()+1):'';
const starts=picks.map(p=>SL[p]);
const pad=n=>String(n).padStart(2,'0');
const slotText=starts.length===5?'כל היום':starts.map(s=>pad(s)+':00-'+pad(s+2)+':00').join(' / ');
const emailSlot=starts.length===5?'כל היום':'שעות '+starts.map(s=>s+'-'+(s+2)).join(' או ');
const chat=norm(input.chat);
const head=(first?'היי '+first+', ':'');
const custLine='👤 '+name+(cn?' (לקוח '+cn+')':'')+'\n📱 '+phone;
let mode, msg;
if(!reason){
  mode='email';
  msg=head+'🙋 הלקוח שלך ביקש בוואטסאפ להקדים את ההתקנה, ושלחתי בקשת הקדמה לחברה:\n\n'+custLine+'\n📅 '+fullDate+'\n🕐 '+slotText+'\n\nאעדכן אותך ברגע שתגיע תשובה מהחברה.';
}else{
  mode='rep';
  msg=head+'🙋 לקוח שלך ענה על הצעת ההקדמה וצריך טיפול שלך:\n\n'+custLine+(target?'\n📅 ההצעה הייתה ל'+offer.replace(/^ב/,'')+' '+shortDate:'')+'\n💬 התשובה שלו: "'+reply+'"\n\n⚠️ '+reason+'.\nתתקשר אליו ותסגור יום וחלון שעות.\n• להיום: דרך משווקים יס (050-2552817)\n• ליום אחר: שולחים לבוט, למשל: הקדמה '+(cn||'<מספר לקוח>')+' 17/11 10-12'+(chat?'\n\n💬 השיחה עם הלקוח: '+chat:'');
}
const alert=JSON.stringify({chatId:(repPh||'972544604246')+'@c.us', message:(repPh?'':'⚠️ לא מצאתי טלפון לנציג "'+rep+'" בלשונית יעדים:\n\n')+msg});
const logBody=JSON.stringify({valueInputOption:'RAW',data:[{range:"'הקדמה מיידית'!O"+(row+1)+':Q'+(row+1),values:[[reply,mode==='email'?'נשלח לחברה '+shortDate+' '+(starts.length===5?'כל היום':starts.map(s=>s+'-'+(s+2)).join(' / ')):'הועבר לנציג: '+reason,stamp]]}]});
return {found:true,mode,alert,logBody,cn,name,rep,repChat:(repPh||'972544604246')+'@c.us',tab,
  email_text:'הלקוח מבקש הקדמה לתאריך '+shortDate+' '+emailSlot+'\nשם הלקוח: '+name,
  full_date:fullDate,slot:slotText,iso_date:target?iso(target):'',today_iso:todayIso,
  sends_today:(sday===todayIso?stoday+1:1),reason};
